package com.aistock.scheduler.alert;
import static com.aistock.scheduler.alert.AlertJobRecords.*;
import java.time.*;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.flywaydb.core.Flyway;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class AlertJobMysqlTest {
 JdbcTemplate jdbc;AlertJobRepository jobs;TestClock clock;
 @BeforeEach void setup(){String url=System.getenv("SCHEDULER_TEST_DB_URL"),password=System.getenv("SCHEDULER_TEST_DB_PASSWORD");if(!"jdbc:mysql://127.0.0.1:13316/stock_scheduler_test?serverTimezone=UTC".equals(url)||password==null)throw new IllegalStateException("Isolated scheduler DB required");jdbc=new JdbcTemplate(new DriverManagerDataSource(url,"root",password));Flyway.configure().dataSource(jdbc.getDataSource()).load().migrate();jdbc.update("delete from alert_job_attempt");jdbc.update("delete from alert_job");jdbc.update("delete from alert_evidence_work");clock=new TestClock();jobs=new AlertJobRepository(jdbc,clock);}
 Input input(UUID raw,UUID rule,String round){return new Input(rule,0,"SH600030",LocalDate.parse("2026-10-09"),raw,round);}
 Job enqueue(){return jobs.enqueue(input(UUID.randomUUID(),UUID.randomUUID(),"round1"));}
 Result available(Claim c,UUID evidence){return new Result(c.attemptId(),"AVAILABLE",evidence,null);}
 @Test void stageProgressionUsesDifferentOperationIdsAndPersistsAcrossRepositoryRestart(){var j=enqueue();var prepare=jobs.claim(clock.instant());var evidence=UUID.randomUUID();assertTrue(jobs.saveEvidence(prepare,evidence));assertEquals("EVALUATE_RULE",jobs.get(j.id()).stage());jobs=new AlertJobRepository(jdbc,clock);var eval=jobs.claim(clock.instant());assertNotEquals(prepare.attemptId(),eval.attemptId());assertEquals(evidence,eval.evidenceId());assertTrue(jobs.finish(eval,new Result(eval.attemptId(),"NOT_MET",null,null)));assertEquals("SUCCEEDED",jobs.get(j.id()).state());assertNull(jobs.claim(clock.instant()));}
 @Test void repeatedRoundsCannotBypassAnUnresolvedAttempt(){var raw=UUID.randomUUID();var rule=UUID.randomUUID();var original=jobs.enqueue(input(raw,rule,"r1"));var claim=jobs.claim(clock.instant());jobs.unknown(claim);assertEquals(original.id(),jobs.enqueue(input(raw,rule,"r2")).id());clock.advance(121);assertEquals(claim.attemptId(),jobs.pendingReceipts().get(0).attemptId());assertNull(jobs.claim(clock.instant()));assertEquals("RECONCILING",jobs.get(original.id()).state());}
 @Test void receiptAfterLeaseMayConfirmRemoteCommitButDirectLateResponseCannot(){var j=enqueue();var claim=jobs.claim(clock.instant());var id=UUID.randomUUID();clock.advance(121);assertFalse(jobs.saveEvidence(claim,id));jobs.unknown(claim);assertTrue(jobs.reconcile(claim,available(claim,id)));assertEquals(id,jobs.get(j.id()).evidenceId());}
 @Test void oldAttemptCannotOverwriteRetryAndRetriesAreBounded(){var j=enqueue();Claim first=null;for(int n=1;n<=3;n++){var c=jobs.claim(clock.instant());assertNotNull(c);if(first==null)first=c;assertTrue(jobs.reconcile(c,new Result(c.attemptId(),"FAILED",null,"SOURCE_UNAVAILABLE")));if(n<3){assertEquals("RETRY_WAIT",jobs.get(j.id()).state());assertNull(jobs.claim(clock.instant()));clock.advance(n==1?60:120);}}assertEquals("FAILED",jobs.get(j.id()).state());assertFalse(jobs.saveEvidence(first,UUID.randomUUID()));assertNull(jobs.claim(clock.instant()));}
 @Test void sameSourceIsPreparedOnceAndSharedWithOtherRules(){var raw=UUID.randomUUID();var a=jobs.enqueue(input(raw,UUID.randomUUID(),"r1"));var b=jobs.enqueue(input(raw,UUID.randomUUID(),"r1"));var prepare=jobs.claim(clock.instant());assertNull(jobs.claim(clock.instant()));var evidence=UUID.randomUUID();assertTrue(jobs.saveEvidence(prepare,evidence));var eval1=jobs.claim(clock.instant());assertEquals("EVALUATE_RULE",eval1.stage());jobs.finish(eval1,new Result(eval1.attemptId(),"NOT_MET",null,null));jobs.claim(clock.instant());var eval2=jobs.claim(clock.instant());if(eval2==null){var running=jobs.pendingReceipts();assertFalse(running.isEmpty());eval2=running.get(0);}assertEquals("EVALUATE_RULE",eval2.stage());assertEquals(evidence,eval2.evidenceId());assertEquals(1,jdbc.queryForObject("select count(*) from alert_job_attempt where stage='PREPARE_EVIDENCE'",Integer.class));}
 @Test void staleSourceEndsJobAndMalformedReceiptDoesNotCommit(){var j=enqueue();var c=jobs.claim(clock.instant());assertThrows(RuntimeException.class,()->jobs.reconcile(c,new Result(UUID.randomUUID(),"AVAILABLE",UUID.randomUUID(),null)));assertEquals("RUNNING",jobs.get(j.id()).state());assertTrue(jobs.reconcile(c,new Result(c.attemptId(),"SKIPPED_STALE",null,null)));assertEquals("SKIPPED",jobs.get(j.id()).state());}
 @Test void concurrentClaimHasOneOwner()throws Exception{enqueue();var pool=Executors.newFixedThreadPool(2);try{var results=pool.invokeAll(List.<Callable<Claim>>of(()->jobs.claim(clock.instant()),()->jobs.claim(clock.instant())));int count=0;for(var r:results)if(r.get()!=null)count++;assertEquals(1,count);}finally{pool.shutdownNow();}}
 @Test void invalidPayloadAndDifferentRawVersionCannotReuseEvidence(){assertThrows(RuntimeException.class,()->jobs.enqueue(new Input(UUID.randomUUID(),-1,"SH600030",LocalDate.parse("2026-10-09"),UUID.randomUUID(),"r1")));var a=enqueue();var c=jobs.claim(clock.instant());jobs.saveEvidence(c,UUID.randomUUID());var b=jobs.enqueue(input(UUID.randomUUID(),UUID.randomUUID(),"r2"));var next=jobs.claim(clock.instant());if("EVALUATE_RULE".equals(next.stage())){jobs.finish(next,new Result(next.attemptId(),"NOT_MET",null,null));next=jobs.claim(clock.instant());}assertEquals("PREPARE_EVIDENCE",next.stage());assertNull(next.evidenceId());}
 @Test void sharedStaleSourceSkipsOtherRulesRatherThanRecordingDependencyFailure(){var raw=UUID.randomUUID();var a=jobs.enqueue(input(raw,UUID.randomUUID(),"r1"));var b=jobs.enqueue(input(raw,UUID.randomUUID(),"r1"));var c=jobs.claim(clock.instant());jobs.reconcile(c,new Result(c.attemptId(),"SKIPPED_STALE",null,null));assertNull(jobs.claim(clock.instant()));assertEquals("SKIPPED",jobs.get(a.id()).state());assertEquals("SKIPPED",jobs.get(b.id()).state());}
 @Test void evaluationRetriesCannotBeOverwrittenByOriginalWorker(){var j=enqueue();var p=jobs.claim(clock.instant());jobs.saveEvidence(p,UUID.randomUUID());var first=jobs.claim(clock.instant());jobs.finish(first,new Result(first.attemptId(),"EVIDENCE_UNAVAILABLE",null,"CHANGE_SOURCE_UNAVAILABLE"));assertEquals("RETRY_WAIT",jobs.get(j.id()).state());clock.advance(60);var second=jobs.claim(clock.instant());assertEquals("EVALUATE_RULE",second.stage());assertNotEquals(first.attemptId(),second.attemptId());assertFalse(jobs.finish(first,new Result(first.attemptId(),"TRIGGERED",UUID.randomUUID(),null)));jobs.finish(second,new Result(second.attemptId(),"SKIPPED_RULE_CHANGED",null,null));assertEquals("SKIPPED",jobs.get(j.id()).state());}
 @Test void expiredSharedEvidenceIsPreparedAgainForFreshRound(){var raw=UUID.randomUUID();var rule=UUID.randomUUID();var j=jobs.enqueue(input(raw,rule,"r1"));jobs.saveEvidence(jobs.claim(clock.instant()),UUID.randomUUID());var eval=jobs.claim(clock.instant());jobs.finish(eval,new Result(eval.attemptId(),"NOT_MET",null,null));clock.advance(301);jobs.enqueue(input(raw,rule,"r2"));assertEquals("PREPARE_EVIDENCE",jobs.claim(clock.instant()).stage());}
 @Test void actualStaleReceiptTerminalizesAndReplaysAcrossRestart(){var j=enqueue();var c=jobs.claim(clock.instant());jobs.unknown(c);clock.advance(121);jobs=new AlertJobRepository(jdbc,clock);assertTrue(jobs.reconcile(c,new Result(c.attemptId(),"SKIPPED_STALE",null,"ALERT_DATE_NOT_LATEST")));assertEquals("SKIPPED",jobs.get(j.id()).state());assertNull(jobs.claim(clock.instant()));assertTrue(jobs.pendingReceipts().isEmpty());}
 @Test void blockedSourceCannotStarveAnotherStockAfterFiftyWaiters(){UUID raw=UUID.randomUUID();enqueue();jdbc.update("delete from alert_job");for(int i=0;i<51;i++)jobs.enqueue(input(raw,UUID.randomUUID(),"r1"));var blocked=jobs.claim(clock.instant());jobs.unknown(blocked);clock.advance(1);jobs.enqueue(new Input(UUID.randomUUID(),0,"SZ000002",LocalDate.parse("2026-10-09"),UUID.randomUUID(),"r1"));var next=jobs.claim(clock.instant());assertNotNull(next,"unrelated stock must remain runnable");assertEquals("SZ000002",next.input().instrumentId());assertEquals(blocked.attemptId(),jdbc.queryForObject("select operation_id from alert_evidence_work where instrument_id='SH600030'",String.class)==null?null:UUID.fromString(jdbc.queryForObject("select operation_id from alert_evidence_work where instrument_id='SH600030'",String.class)));}
 static class TestClock extends Clock {Instant now=Instant.parse("2026-10-10T08:00:00Z");void advance(long seconds){now=now.plusSeconds(seconds);}public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return Clock.fixed(now,zone);}public Instant instant(){return now;}}
 @Test void explicitUseDenialDoesNotRetrySharedPreparationOrSwapRaw(){var job=enqueue();var c=jobs.claim(clock.instant());var raw=c.input().rawVersionId();assertTrue(jobs.finish(c,new Result(c.attemptId(),"FAILED",null,"MARKET_VERSION_USE_BLOCKED")));assertEquals("FAILED",jobs.get(job.id()).state());clock.advance(3600);assertNull(jobs.claim(clock.instant()));assertEquals(raw,jobs.get(job.id()).input().rawVersionId());assertEquals(1,jdbc.queryForObject("select count(*) from alert_job_attempt where job_id=?",Integer.class,job.id().toString()));}

}
